    auto in1 = FlatVector::GetData<double>(args.data[1]);
    auto in2 = FlatVector::GetData<double>(args.data[2]);
    auto in3 = FlatVector::GetData<double>(args.data[3]);
    auto in4 = FlatVector::GetData<double>(args.data[4]);
